import React from "react";
import {
  NavLink,
  Outlet,
  useNavigate
} from "react-router-dom";

import {
  BarChart3,
  Boxes,
  CircleDollarSign,
  FileText,
  Home,
  Leaf,
  LogOut,
  PackageCheck,
  ReceiptText,
  Sprout,
  UserRound,
  Users,
  Bell,
  MessageSquareWarning
} from "lucide-react";

const links = [

  // Dashboard
  ["Dashboard", "/dashboard", Home],

  // Members
  ["Members", "/members", Users],

  // Procurement
  ["Procurement", "/procurement", PackageCheck],

  // Passbook
  ["Passbook", "/passbook", ReceiptText],

  // Share Capital
  ["Share Capital", "/share-capital", CircleDollarSign],

  // Sales
  ["Sales Orders", "/sales", Boxes],

  // Warehouse
  ["Warehouse", "/warehouse", Sprout],

  // Analytics
  ["Analytics", "/analytics", BarChart3],

  // Reports
  ["NABARD Report", "/reports", FileText],

  // Dividend
  ["Dividend", "/dividend", CircleDollarSign],

  // Notifications
  ["Notifications", "/notifications", Bell],

  // Unique module
  ["Grievances", "/grievances", MessageSquareWarning],

  // Profile
  ["Profile", "/profile", UserRound]
];

export default function Layout() {

  const navigate = useNavigate();

  const name =
      localStorage.getItem("name") || "User";

  const role =
      localStorage.getItem("role") || "";

  const logout = () => {

    localStorage.clear();

    navigate("/login");
  };

  return (
      <div className="app-shell">

        {/* ================= SIDEBAR ================= */}

        <aside className="sidebar">

          {/* Brand */}

          <div className="brand">

            <div className="brand-mark">
              <Leaf size={24} />
            </div>

            <div>
              <strong>FPO</strong>
              <span>Management</span>
            </div>

          </div>


          {/* Navigation */}

          <nav>

            {links.map(
                ([label, path, Icon]) => (

                    <NavLink
                        key={path}
                        to={path}
                        className={({ isActive }) =>
                            isActive
                                ? "nav-link active"
                                : "nav-link"
                        }
                    >

                      <Icon size={18} />

                      <span>
                  {label}
                </span>

                    </NavLink>

                )
            )}

          </nav>


          {/* Logout */}

          <button
              className="logout"
              onClick={logout}
          >

            <LogOut size={18} />

            <span>
            Logout
          </span>

          </button>

        </aside>


        {/* ================= MAIN AREA ================= */}

        <main className="main-area">

          {/* Top Header */}

          <header className="topbar">

            <div>

            <span className="eyebrow">
              AGRICULTURAL COOPERATIVE
            </span>

              <h1>
                Farmer Producer Organisation
              </h1>

            </div>


            {/* User */}

            <div className="user-chip">

              <div className="avatar">

                {name.charAt(0).toUpperCase()}

              </div>

              <div>

                <b>
                  {name}
                </b>

                <small>
                  {role
                      ? role.replaceAll("_", " ")
                      : "USER"}
                </small>

              </div>

            </div>

          </header>


          {/* Page Content */}

          <section className="content">

            <Outlet />

          </section>

        </main>

      </div>
  );
}
